SELECT n.Nm, InNames = CASE WHEN EXISTS (SELECT 1 FROM dbo.HS_Team_Names t WHERE t.Team_Name = n.Nm) THEN 1 ELSE 0 END, Games = (SELECT COUNT(*) FROM dbo.HS_Scores s WHERE s.Home = n.Nm OR s.Visitor = n.Nm)
FROM (VALUES ('Palestine (AR)'),('Amity (AR)'),('Little Rock Southwest (AR)'),('Des Arc (AR)'),('DesArc (AR)'),('West Helena Woodruff (AR)'),('Hartman (AR)'),('Arkansas School for the Deaf (AR)'),('Little Rock Arkansas School (AR)'),('North Little Rock (AR)'),('Hartman Coal Hill Westside (AR)'),('Maumelle (AR)'),('North Little Rock Oak Grove (AR)'),('Marianna Lee (AR)'),('Marianna (AR)'),('Fort Smith Northside (AR)'),('Fort Smith (AR)')) n(Nm);
